<?php
namespace Tests\Feature\Customer;
use App\Models\BannedWord;use App\Models\Category;use App\Models\Color;use App\Models\Order;use App\Models\OrderItem;use App\Models\Product;use App\Models\Review;use App\Models\Size;use App\Models\User;use App\Services\ReviewModerationService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;use Tests\TestCase;
class Phase7ReviewTest extends TestCase
{
 use RefreshDatabase;private int $n=0;private function user(string $role='customer'):User{return User::factory()->create(['role'=>$role,'status'=>'active']);}
 private function product():Product{$this->n++;$c=Category::create(['name'=>'C'.$this->n,'slug'=>'c'.$this->n,'status'=>'active']);return Product::create(['category_id'=>$c->id,'name'=>'Shirt '.$this->n,'slug'=>'shirt-'.$this->n,'sku'=>'P'.$this->n,'price'=>100000,'status'=>'active']);}
 private function eligible(User $u,Product $p,string $status='completed'):OrderItem{$this->n++;$co=Color::create(['name'=>'N'.$this->n,'hex_code'=>'#112233','status'=>'active']);$s=Size::create(['name'=>'M'.$this->n,'status'=>'active']);$v=$p->variants()->create(['color_id'=>$co->id,'size_id'=>$s->id,'sku'=>'V'.$this->n,'stock'=>2]);$o=Order::create(['user_id'=>$u->id,'order_code'=>'ORD20260827'.str_pad((string)$this->n,8,'0',STR_PAD_LEFT),'checkout_token'=>fake()->uuid(),'recipient_name'=>$u->name,'email'=>$u->email,'phone'=>'1','province'=>'P','district'=>'D','ward'=>'W','address'=>'A','subtotal'=>100000,'discount'=>0,'shipping_fee'=>0,'total'=>100000,'status'=>$status]);return OrderItem::create(['order_id'=>$o->id,'product_variant_id'=>$v->id,'product_name'=>$p->name,'product_sku'=>$p->sku,'color_name'=>$co->name,'size_name'=>$s->name,'price'=>100000,'quantity'=>1,'subtotal'=>100000]);}
 private function review(User $u,Product $p,string $status='pending',int $rating=5,string $content='San pham rat tot'):Review{$item=$this->eligible($u,$p);return Review::create(['user_id'=>$u->id,'product_id'=>$p->id,'order_item_id'=>$item->id,'rating'=>$rating,'content'=>$content,'status'=>$status,'verified_purchase'=>true]);}
 private function submit(User $u,Product $p,array $d=[]){return $this->actingAs($u)->post('/products/'.$p->id.'/reviews',array_merge(['rating'=>5,'content'=>'San pham rat dep va tot'],$d));}
 public function test_completed_order_customer_can_review():void{$u=$this->user();$p=$this->product();$this->eligible($u,$p);$this->submit($u,$p)->assertSessionHasNoErrors();$this->assertDatabaseHas('reviews',['user_id'=>$u->id,'product_id'=>$p->id]);}
 public function test_customer_without_completed_order_cannot_review():void{$this->submit($this->user(),$this->product())->assertSessionHasErrors('review');}
 public function test_pending_order_cannot_review():void{$u=$this->user();$p=$this->product();$this->eligible($u,$p,'pending');$this->submit($u,$p)->assertSessionHasErrors('review');}
 public function test_cancelled_order_cannot_review():void{$u=$this->user();$p=$this->product();$this->eligible($u,$p,'cancelled');$this->submit($u,$p)->assertSessionHasErrors('review');}
 public function test_rating_below_one_rejected():void{$u=$this->user();$p=$this->product();$this->eligible($u,$p);$this->submit($u,$p,['rating'=>0])->assertSessionHasErrors('rating');}
 public function test_rating_above_five_rejected():void{$u=$this->user();$p=$this->product();$this->eligible($u,$p);$this->submit($u,$p,['rating'=>6])->assertSessionHasErrors('rating');}
 public function test_review_starts_pending():void{$u=$this->user();$p=$this->product();$this->eligible($u,$p);$this->submit($u,$p);$this->assertSame('pending',Review::first()->status);}
 public function test_pending_review_not_public():void{$u=$this->user();$p=$this->product();$this->review($u,$p,'pending',5,'Pending private');$this->get('/products/'.$p->slug)->assertDontSee('Pending private');}
 public function test_approved_review_public():void{$u=$this->user();$p=$this->product();$this->review($u,$p,'approved',5,'Approved public');$this->get('/products/'.$p->slug)->assertSee('Approved public');}
 public function test_rejected_review_not_public():void{$u=$this->user();$p=$this->product();$this->review($u,$p,'rejected',5,'Rejected private');$this->get('/products/'.$p->slug)->assertDontSee('Rejected private');}
 public function test_hidden_review_not_public():void{$u=$this->user();$p=$this->product();$this->review($u,$p,'hidden',5,'Hidden private');$this->get('/products/'.$p->slug)->assertDontSee('Hidden private');}
 public function test_average_rating_counts_approved_only():void{$p=$this->product();$this->review($this->user(),$p,'approved',5);$this->review($this->user(),$p,'approved',3);$this->review($this->user(),$p,'pending',1);$this->assertEquals(4,$p->average_rating);$this->assertEquals(2,$p->approved_reviews_count);}
 public function test_verified_purchase_correct():void{$u=$this->user();$p=$this->product();$this->eligible($u,$p);$r=app(ReviewModerationService::class)->create($u,$p,['rating'=>5,'content'=>'Verified purchase review']);$this->assertTrue($r->verified_purchase);$this->assertNotNull($r->order_item_id);}
 public function test_admin_reviews_page_200():void{$this->actingAs($this->user('admin'))->get('/admin/reviews')->assertOk();}
 public function test_customer_blocked_admin_reviews():void{$this->actingAs($this->user())->get('/admin/reviews')->assertForbidden();}
 public function test_admin_approves_pending_review():void{$r=$this->review($this->user(),$this->product());app(ReviewModerationService::class)->transition($r,'approved',$this->user('admin'));$this->assertSame('approved',$r->fresh()->status);}
 public function test_admin_rejects_pending_review():void{$r=$this->review($this->user(),$this->product());app(ReviewModerationService::class)->transition($r,'rejected',$this->user('admin'));$this->assertSame('rejected',$r->fresh()->status);}
 public function test_admin_hides_approved_review():void{$r=$this->review($this->user(),$this->product(),'approved');app(ReviewModerationService::class)->transition($r,'hidden',$this->user('admin'));$this->assertSame('hidden',$r->fresh()->status);}
 public function test_hidden_review_can_be_restored():void{$r=$this->review($this->user(),$this->product(),'hidden');app(ReviewModerationService::class)->transition($r,'approved',$this->user('admin'));$this->assertSame('approved',$r->fresh()->status);}
 public function test_banned_word_detected():void{$u=$this->user();$p=$this->product();$this->eligible($u,$p);BannedWord::create(['word'=>'xau xa','status'=>'active']);$this->submit($u,$p,['content'=>'Noi dung xau xa khong hop le'])->assertSessionHasErrors('content');$this->assertDatabaseCount('reviews',0);}
 public function test_inactive_banned_word_ignored():void{$u=$this->user();$p=$this->product();$this->eligible($u,$p);BannedWord::create(['word'=>'xau xa','status'=>'inactive']);$this->submit($u,$p,['content'=>'Noi dung xau xa nhung duoc phep'])->assertSessionHasNoErrors();$this->assertDatabaseCount('reviews',1);}
 public function test_review_rate_limit_works():void{$u=$this->user();for($i=0;$i<6;$i++){$p=$this->product();$this->eligible($u,$p);$response=$this->submit($u,$p);} $response->assertTooManyRequests();}
 public function test_duplicate_review_prevented():void{$u=$this->user();$p=$this->product();$this->eligible($u,$p);$this->submit($u,$p);$this->submit($u,$p)->assertSessionHasErrors('review');$this->assertEquals(1,Review::count());}
 public function test_customer_review_history_ownership():void{$u=$this->user();$mine=$this->review($u,$this->product(),'pending',5,'My private review');$other=$this->review($this->user(),$this->product(),'pending',5,'Other private review');$this->actingAs($u)->get('/account/reviews')->assertSee($mine->content)->assertDontSee($other->content);}
 public function test_script_html_content_rendered_safely():void{$p=$this->product();$this->review($this->user(),$p,'approved',5,'<script>alert(1)</script>');$this->get('/products/'.$p->slug)->assertSee('&lt;script&gt;alert(1)&lt;/script&gt;',false)->assertDontSee('<script>alert(1)</script>',false);}
}
